const lookupLeakGuardFingerprints = `-- name: LookupLeakGuardFingerprints :many
SELECT DISTINCT fp FROM leak_guard_fingerprints
WHERE org_id = $1 AND agent_id = $2 AND generation = $3
  AND fp = ANY ($4::bigint[])
`

type LookupLeakGuardFingerprintsParams struct {
	OrgID      pgtype.UUID
	AgentID    pgtype.UUID
	Generation string
	Fps        []int64
}

// The fingerprints of @fps the session holds.
func (q *Queries) LookupLeakGuardFingerprints(ctx context.Context, arg LookupLeakGuardFingerprintsParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, lookupLeakGuardFingerprints,
		arg.OrgID,
		arg.AgentID,
		arg.Generation,
		arg.Fps,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var fp int64
		if err := rows.Scan(&fp); err != nil {
			return nil, err
		}
		items = append(items, fp)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

